#!/usr/bin/env bash
# Hardware-forwarded opposite-node paths for RoCEnante (generated by spark/ring/mesh/plan.py). Idempotent.
set -euo pipefail
tc qdisc show dev enP2p1s0f0np0 | grep clsact >/dev/null || tc qdisc add dev enP2p1s0f0np0 clsact
tc qdisc show dev enP2p1s0f1np1 | grep clsact >/dev/null || tc qdisc add dev enP2p1s0f1np1 clsact
tc filter show dev enP2p1s0f1np1 ingress pref 49155 | grep flower >/dev/null || tc filter add dev enP2p1s0f1np1 ingress protocol 0x88b5 pref 49155 handle 49155 flower skip_sw src_mac 4c:bb:47:80:f1:47 dst_mac 4c:bb:47:80:ab:b4 action pedit ex munge eth type set 0x0800 pipe action pedit ex munge eth dst set 4c:bb:47:80:b2:10 pipe action mirred egress redirect dev enP2p1s0f0np0
tc -s filter show dev enP2p1s0f1np1 ingress pref 49155 | grep in_hw >/dev/null || { echo 'rule pref 49155 on enP2p1s0f1np1 is not in hardware'; exit 3; }
tc filter show dev enP2p1s0f0np0 ingress pref 49161 | grep flower >/dev/null || tc filter add dev enP2p1s0f0np0 ingress protocol 0x88b5 pref 49161 handle 49161 flower skip_sw src_mac 4c:bb:47:80:b2:10 dst_mac 4c:bb:47:80:ab:b3 action pedit ex munge eth type set 0x0800 pipe action pedit ex munge eth dst set 4c:bb:47:80:f1:47 pipe action mirred egress redirect dev enP2p1s0f1np1
tc -s filter show dev enP2p1s0f0np0 ingress pref 49161 | grep in_hw >/dev/null || { echo 'rule pref 49161 on enP2p1s0f0np0 is not in hardware'; exit 3; }
ip route show exact 10.100.241.2/32 | grep . >/dev/null || ip route add 10.100.241.2/32 via 10.100.241.14 dev enP2p1s0f1np1 src 10.100.241.13
ip route show exact 10.251.20.5/32 | grep . >/dev/null || ip route add 10.251.20.5/32 via 10.251.20.9 dev enp1s0f0np0 src 10.251.20.10
for d in roceP2p1s0f1 rocep1s0f0; do systemctl start spark-ring-mesh-marker@$d; done
sleep 2; for d in roceP2p1s0f1 rocep1s0f0; do systemctl is-active --quiet spark-ring-mesh-marker@$d || { echo marker $d not active; exit 4; }; done
echo mesh-up OK
